insert into public.monthly_tips(month,risk_level,title,content) values
(1,'low','Month 1: Early Pregnancy Care','Eat a variety of healthy foods: vegetables, fruits, whole grains, beans, nuts, fish, lean meat, eggs, and milk. Start or continue folic acid and iron supplements as prescribed by a health worker. Drink enough clean water and avoid alcohol.'),
(2,'low','Month 2: Continued Nutrition','Continue a balanced diet with protein-rich foods such as fish, eggs, chicken, beans, and tofu. Include iron-rich foods such as malunggay, dark leafy vegetables, liver in moderation, beans, and fortified cereals. Take vitamin C-rich foods like calamansi, guava, or orange to help iron absorption.'),
(3,'low','Month 3: First Trimester Complete','Eat small, frequent meals if experiencing nausea or poor appetite. Choose easy-to-digest foods such as rice, congee, crackers, banana, soup, and yogurt. Avoid very oily, spicy, or strong-smelling foods if they worsen nausea. Continue prenatal vitamins as prescribed.'),
(4,'low','Month 4: Second Trimester Begins','Increase intake of calcium-rich foods such as milk, yogurt, cheese, small fish with edible bones, tofu, and green leafy vegetables. Include protein foods to support fetal growth. Limit sweetened drinks, chips, and processed foods.'),
(5,'low','Month 5: Baby Growing Strong','Maintain regular meals with whole grains, vegetables, fruits, and protein. Monitor weight gain according to the advice of the health provider. Continue iron and folic acid supplementation as prescribed.'),
(6,'low','Month 6: Halfway There','Prioritize iron-rich foods to help prevent anemia, especially if carrying twins or triplets or if there is a history of anemia. Pair iron-rich foods with vitamin C sources. Avoid taking tea or coffee together with iron supplements or iron-rich meals because they may reduce iron absorption.'),
(7,'low','Month 7: Third Trimester Begins','Eat enough protein and calories to support rapid fetal growth, but avoid excessive weight gain. Choose healthy snacks such as fruit, nuts, yogurt, boiled egg, or whole-grain crackers instead of sugary snacks. Continue calcium-rich foods and prescribed supplements.'),
(8,'low','Month 8: Getting Ready','Eat smaller but more frequent meals if there is heartburn, bloating, or difficulty eating large meals. Continue balanced meals and adequate fluid intake. Avoid alcohol; limit caffeine to no more than 200 mg per day, or about one 12-ounce cup of coffee.'),
(9,'low','Month 9: Almost There','Continue regular, balanced meals and healthy snacks. Prepare easy-to-digest meals and keep nutritious foods available for the postpartum period. Follow the doctor''s advice regarding fluid intake, salt restriction, or special diet if there is hypertension, diabetes, kidney disease, or other medical conditions.')
